  "Nous contacter": { en: "Contact us", es: "Contáctanos", ar: "تواصل معنا" },
  "Merci pour votre retour ! 🙏": { en: "Thanks for your feedback! 🙏", es: "¡Gracias por tu opinión! 🙏", ar: "شكراً على ملاحظتك! 🙏" },
  "Merci — nous allons améliorer cet article.": { en: "Thanks — we'll improve this article.", es: "Gracias — mejoraremos este artículo.", ar: "شكراً — سنعمل على تحسين هذا المقال." },
