  "Vous avez besoin d'une aide personnalisée ?": { en: "Need personalized help?", es: "¿Necesitas ayuda personalizada?", ar: "هل تحتاج إلى مساعدة شخصية؟" },
  "Écrire au support": { en: "Write to support", es: "Escribir al soporte", ar: "مراسلة الدعم" },
  "besoin d'aide ?": { en: "need help?", es: "¿necesitas ayuda?", ar: "هل تحتاج مساعدة؟" },
  "Trouvez des réponses, explorez les guides et prenez la route sans inquiétude.": { en: "Find answers, explore guides and hit the road worry-free.", es: "Encuentra respuestas, explora las guías y pon rumbo sin preocupaciones.", ar: "اعثر على إجاباتك، استكشف الأدلة وانطلق في رحلتك بلا قلق." },
  "SUPPORT\n★\n24/7": { en: "SUPPORT\n★\n24/7", es: "SOPORTE\n★\n24/7", ar: "دعم\n★\n24/7" },
  "Rechercher dans l'aide": { en: "Search the help center", es: "Buscar en la ayuda", ar: "البحث في المساعدة" },
  "Ex : karma, photo, abonnement…": { en: "E.g. karma, photo, subscription…", es: "Ej: karma, foto, suscripción…", ar: "مثال: كارما، صورة، اشتراك…" },
  "Aucun résultat pour « {{query}} »": { en: "No results for « {{query}} »", es: "Sin resultados para « {{query}} »", ar: "لا نتائج لـ « {{query}} »" },
